#!/usr/bin/env bash
# Per-user DXVK 2.7 launcher. No session timeout and no authentication helpers.
set -euo pipefail
umask 077
fail() {
  printf '%s\n' "$1" >&2
  if command -v notify-send >/dev/null 2>&1; then
    notify-send 'WoW HD620 experimental (DXVK 2.7)' "$1" || true
  fi
  exit 1
}
config="${XDG_CONFIG_HOME:-$HOME/.config}/wow-hd620-experimental/runtime.conf"
[[ -f "$config" && ! -L "$config" ]] || fail 'The private HD620 runtime configuration is missing or is a symlink.'
# Generated by the installer with shell-escaped, canonical local paths.
source "$config"
[[ -n "${HD620_RUNTIME:-}" && -n "${HD620_PREFIX:-}" && -n "${HD620_LIBEXEC:-}" ]] || fail 'The HD620 runtime configuration is incomplete.'
for tool in realpath sha256sum; do
  command -v "$tool" >/dev/null || fail "Required tool is missing: $tool"
done
runtime=$(realpath -e -- "$HD620_RUNTIME") || fail 'The pinned experimental runtime is missing.'
[[ "$runtime" == "$HD620_RUNTIME" && -f "$runtime/proton" ]] || fail 'The pinned runtime path changed or its Proton entrypoint is missing.'
dll_dir="$runtime/files/lib/wine/dxvk/x86_64-windows"
for dll in d3d11.dll dxgi.dll; do
  [[ -f "$dll_dir/$dll" ]] || fail "The pinned runtime is missing $dll."
  resolved=$(realpath -e -- "$dll_dir/$dll") || fail "Cannot resolve $dll."
  [[ "$resolved" == "$runtime/"* ]] || fail "$dll resolves outside the experimental runtime; refusing to follow it."
done
[[ -f "$HD620_LIBEXEC/DLL-SHA256SUMS" ]] || fail 'The pinned DLL checksum manifest is missing.'
if ! (cd "$dll_dir" && sha256sum --status -c "$HD620_LIBEXEC/DLL-SHA256SUMS"); then
  fail 'The guarded DXVK 2.7 DLL pair changed or is mixed. Restore the verified pair; do not disable the guard.'
fi
[[ -d "$HD620_PREFIX/drive_c" ]] || fail 'The configured game prefix is missing.'
[[ -x "$HD620_LIBEXEC/launch.sh" ]] || fail 'The installed HD620 launch helper is missing or not executable.'
# Do not let an ambient override select the stock runtime or WineD3D instead.
export WOW_PROTON="$runtime" WOW_PREFIX="$HD620_PREFIX" WOW_WAYLAND=0
unset PROTON_USE_WINED3D PROTON_NO_D3D11
exec "$HD620_LIBEXEC/launch.sh" "$@"
